import type { CSSProperties } from "react";
import type { AlbumConfig, CoverStyleType } from "../types";
import { backgroundStyle } from "../utils/background";
import { FloralFrame } from "./FloralFrame";
import { GoldCorners } from "./GoldCorners";

export interface CoverWrapperProps {
  album: AlbumConfig;
  face: "front" | "back";
}

const BACK_COVER_TITLE = "בהוקרה ובאהבה";
const BACK_COVER_SUBTITLE = "תודה שהייתם חלק מהאלבום הזה";

/**
 * Intercepts index point zero (and the mirrored closing index) during
 * compilation. Instead of a normal body slot it maps a dedicated template
 * selected by `CoverStyleType`, all sharing the same RTL title stack.
 */
export function CoverWrapper({ album, face }: CoverWrapperProps) {
  const style: CoverStyleType = album.coverStyle ?? "MINIMAL";
  const isFront = face === "front";

  const title = isFront
    ? (album.coverTitle?.trim() || album.title)
    : BACK_COVER_TITLE;
  const subtitle = isFront
    ? album.coverSubtitle?.trim() || null
    : BACK_COVER_SUBTITLE;
  const heroUrl = isFront ? album.coverImageUrl?.trim() || null : null;

  // PHOTO_FULL bleeds the hero to the edges and floats the title over it;
  // without an image it degrades to the plain album backdrop.
  const isPhotoFull = style === "PHOTO_FULL";
  const bleedUrl = isPhotoFull ? heroUrl : null;
  const insetUrl = isPhotoFull ? null : heroUrl;

  // A photo bleed and the foil ground each dictate their own surface, so the
  // owner's background and text colour only apply to the templates that sit on
  // the album's own backdrop.
  const isFoil = style === "GOLD_FOIL";
  const surface: CSSProperties = isFoil
    ? {}
    : backgroundStyle(bleedUrl ?? album.globalBackground);
  if (!bleedUrl && !isFoil) {
    surface.color = album.coverTextColor || "#1E3A8A";
  }

  return (
    <div
      className={`ae-cover ae-cover--${slug(style)} ae-cover--${face}${
        bleedUrl ? " ae-cover--bleed" : ""
      }`}
      style={surface}
    >
      <div className="ae-cover__ornament" aria-hidden="true" />
      {style === "GOLD_FOIL" ? <GoldCorners /> : null}

      {insetUrl ? (
        <div className="ae-cover__hero">
          <img src={insetUrl} alt="" />
        </div>
      ) : null}

      <div className="ae-cover__titles">
        {style === "FLORAL_FRAME" ? <FloralFrame side="start" /> : null}
        <div className="ae-cover__text">
          <h1 className="ae-cover__title">{title}</h1>
          {subtitle ? <p className="ae-cover__subtitle">{subtitle}</p> : null}
          <span className="ae-cover__rule" aria-hidden="true" />
        </div>
        {style === "FLORAL_FRAME" ? <FloralFrame side="end" /> : null}
      </div>
    </div>
  );
}

function slug(style: CoverStyleType): string {
  return style.toLowerCase().replace(/_/g, "-");
}
